const o={pricing:"/pricing",history:"/history"},a=e=>[{question:e.faq.q1,answer:e.faq.a1},{question:e.faq.q2,answer:e.faq.a2},{question:e.faq.q3,answer:e.faq.a3},{question:e.faq.q4,answer:e.faq.a4},{question:e.faq.q5,answer:e.faq.a5},{question:e.faq.q6,answer:e.faq.a6},{question:e.faq.q7,answer:e.faq.a7,href:o.pricing,linkText:e.faq.link7},{question:e.faq.q8,answer:e.faq.a8,href:o.history,linkText:e.faq.link8}],t="About LimeWire AI Studio",n="LimeWire AI Studio turns a written description into an image or a video, in the browser, with nothing to install. It sits next to your files: what you generate lands in the same activity list as what you upload, so a picture made here can be shared by link exactly like any other file on LimeWire.",i="Models you can pick",s=[{name:"Google Gemini 2.5",note:"The default for images. Follows long, detailed descriptions closely."},{name:"Stable Diffusion Core",note:"A fast general-purpose image model for everyday prompts."},{name:"Stable Diffusion Ultra",note:"The heavier Stable Diffusion option, for when detail matters more than speed."},{name:"Stable Diffusion XL v1.0",note:"The classic SDXL checkpoint, familiar to anyone who has used it elsewhere."}],r="AI Studio: frequently asked questions",l=[{question:"What can I make in LimeWire AI Studio?",answer:"Two things, on two tabs. Image turns your description into a picture, with a choice of model. Video turns a description into a short clip. Both run in the browser — there is nothing to install and nothing to set up."},{question:"Which AI models are available?",answer:"For images: Google Gemini 2.5, Stable Diffusion Core, Stable Diffusion Ultra and Stable Diffusion XL v1.0. The same words give different results on different models, so it is worth trying more than one."},{question:"Is it free, and what do credits mean?",answer:"Generating spends credits, and every account gets 60 free AI credits a week — the same allowance on every plan. The Generate button shows what the current generation costs before you press it, so the price is never a surprise."},{question:"Do I need an account to use AI Studio?",answer:"You can start without one. Without an account your files expire after three days and downloads are limited; a free account keeps them for seven days and lifts the download limits, and a paid plan keeps files longer and raises the upload size."},{question:"Where do my generated images and videos go?",answer:"Into My Activity, the same list that holds the files you upload. From there a result can be downloaded or shared by link, like any other file on LimeWire."},{question:"What is not allowed?",answer:"No nudity, sexual content or other adult material — not in uploads, not in prompts, not in generated results. Violations block the generation and can suspend the account."},{question:"How is AI Studio different from the LimeWire file tools?",answer:"AI Studio makes something new from a description. The file tools work on a file you already have: convert it, compress it, merge it or edit it. Both are free to start and both run in the browser."}];export{l as A,r as a,n as b,s as c,i as d,t as e,a as l};
